-- supabase/sql/exam_question_bank_ssc_cgl_set1.sql
--
-- First curated question-bank batch for 'SSC-CGL' (see exam_patterns_ssc_cgl.sql for the exam's
-- structure). Same exam_question_bank table/schema as the other sets -- no migration needed.
--
-- Every row here is format='mcq' with a single isCorrect:true option (100% single-best-response,
-- matching the real Tier I exam). The "General Awareness" chapters stick to durable, evergreen
-- static facts rather than time-sensitive news. Non-verbal reasoning is normally figure-based
-- (mirror images, figure counting) and can't be rendered as images here, so that chapter instead
-- uses the classic numeric cube-painting/paper-folding puzzles that SSC exams commonly phrase in
-- pure text. 16 chapters (4 per section x 4 sections) each get 4 questions.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_ssc_cgl.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

-- General Intelligence and Reasoning: Verbal Reasoning (Analogies, Classification, Series)
('SSC-CGL', 'General Intelligence and Reasoning', 'Verbal Reasoning (Analogies, Classification, Series)', 'easy', 'mcq',
 'Complete the analogy: Doctor is to Hospital as Teacher is to:',
 '[{"text":"Classroom","isCorrect":false},{"text":"School","isCorrect":true},{"text":"Book","isCorrect":false},{"text":"Student","isCorrect":false}]'::jsonb,
 null, 'A doctor primarily works at a hospital; the analogous primary workplace for a teacher is a school, the broader institution.'),
('SSC-CGL', 'General Intelligence and Reasoning', 'Verbal Reasoning (Analogies, Classification, Series)', 'easy', 'mcq',
 'Find the odd one out: Apple, Mango, Potato, Banana.',
 '[{"text":"Apple","isCorrect":false},{"text":"Mango","isCorrect":false},{"text":"Potato","isCorrect":true},{"text":"Banana","isCorrect":false}]'::jsonb,
 null, 'Apple, Mango, and Banana are all fruits, while Potato is a vegetable, making it the odd one out.'),
('SSC-CGL', 'General Intelligence and Reasoning', 'Verbal Reasoning (Analogies, Classification, Series)', 'medium', 'mcq',
 'Find the next number in the series: 3, 9, 27, 81, ?',
 '[{"text":"162","isCorrect":false},{"text":"243","isCorrect":true},{"text":"216","isCorrect":false},{"text":"324","isCorrect":false}]'::jsonb,
 null, 'Each term is multiplied by 3 to get the next term, so after 81 the next term is 81*3=243.'),
('SSC-CGL', 'General Intelligence and Reasoning', 'Verbal Reasoning (Analogies, Classification, Series)', 'medium', 'mcq',
 'Find the odd one out: 8, 27, 64, 100.',
 '[{"text":"8","isCorrect":false},{"text":"27","isCorrect":false},{"text":"64","isCorrect":false},{"text":"100","isCorrect":true}]'::jsonb,
 null, '8, 27, and 64 are perfect cubes (2^3, 3^3, 4^3), while 100 is not a perfect cube, making it the odd one out.'),

-- General Intelligence and Reasoning: Non-Verbal and Figural Reasoning
('SSC-CGL', 'General Intelligence and Reasoning', 'Non-Verbal and Figural Reasoning', 'medium', 'mcq',
 'A cube is painted red on all its faces and then cut into 27 equal smaller cubes. How many of the smaller cubes have exactly one face painted red?',
 '[{"text":"6","isCorrect":true},{"text":"8","isCorrect":false},{"text":"12","isCorrect":false},{"text":"1","isCorrect":false}]'::jsonb,
 null, 'In a 3x3x3 cube, the single cube at the center of each of the 6 faces has exactly one painted face, giving 6 such cubes.'),
('SSC-CGL', 'General Intelligence and Reasoning', 'Non-Verbal and Figural Reasoning', 'medium', 'mcq',
 'A cube is painted red on all its faces and cut into 27 equal smaller cubes. How many smaller cubes have no face painted at all?',
 '[{"text":"0","isCorrect":false},{"text":"1","isCorrect":true},{"text":"8","isCorrect":false},{"text":"27","isCorrect":false}]'::jsonb,
 null, 'Only the single cube at the very center of the 3x3x3 arrangement, completely surrounded by other cubes, has no painted face.'),
('SSC-CGL', 'General Intelligence and Reasoning', 'Non-Verbal and Figural Reasoning', 'medium', 'mcq',
 'A square sheet of paper is folded in half twice (into quarters), and then a hole is punched through the folded center. How many holes will appear when the paper is fully unfolded?',
 '[{"text":"1","isCorrect":false},{"text":"2","isCorrect":false},{"text":"4","isCorrect":true},{"text":"8","isCorrect":false}]'::jsonb,
 null, 'Folding a sheet in half twice creates 4 layers; punching through the center of all 4 layers produces 4 holes when the paper is unfolded.'),
('SSC-CGL', 'General Intelligence and Reasoning', 'Non-Verbal and Figural Reasoning', 'hard', 'mcq',
 'A cube is painted red on all its faces and cut into 64 equal smaller cubes (a 4x4x4 arrangement). How many smaller cubes have exactly two faces painted red?',
 '[{"text":"12","isCorrect":false},{"text":"24","isCorrect":true},{"text":"8","isCorrect":false},{"text":"36","isCorrect":false}]'::jsonb,
 null, 'In a 4x4x4 cube, each of the 12 edges has 2 non-corner cubes with exactly two painted faces, giving 12*2=24 such cubes.'),

-- General Intelligence and Reasoning: Logical Reasoning (Syllogism, Statements and Conclusions)
('SSC-CGL', 'General Intelligence and Reasoning', 'Logical Reasoning (Syllogism, Statements and Conclusions)', 'medium', 'mcq',
 'Given: "All pens are pencils" and "All pencils are erasers." Which conclusion follows?',
 '[{"text":"All pens are erasers.","isCorrect":true},{"text":"All erasers are pens.","isCorrect":false},{"text":"No pens are erasers.","isCorrect":false},{"text":"Some pencils are not erasers.","isCorrect":false}]'::jsonb,
 null, 'By transitive syllogism, since all pens are pencils and all pencils are erasers, it necessarily follows that all pens are erasers.'),
('SSC-CGL', 'General Intelligence and Reasoning', 'Logical Reasoning (Syllogism, Statements and Conclusions)', 'hard', 'mcq',
 'Statement: "All cats are black." Conclusion I: Some black things are cats. Conclusion II: No cats are white. Which of the conclusions logically follow(s)?',
 '[{"text":"Only Conclusion I follows","isCorrect":true},{"text":"Only Conclusion II follows","isCorrect":false},{"text":"Both conclusions follow","isCorrect":false},{"text":"Neither conclusion follows","isCorrect":false}]'::jsonb,
 null, '"All cats are black" implies at least some black things are cats (Conclusion I follows), but it does not by itself rule out the possibility of non-black cats existing outside this specific statement''s scope in strict syllogistic terms, so Conclusion II does not strictly follow.'),
('SSC-CGL', 'General Intelligence and Reasoning', 'Logical Reasoning (Syllogism, Statements and Conclusions)', 'medium', 'mcq',
 'Given: "Some A are B" and "All B are C." Which conclusion follows?',
 '[{"text":"Some A are C.","isCorrect":true},{"text":"All A are C.","isCorrect":false},{"text":"No A are C.","isCorrect":false},{"text":"All C are A.","isCorrect":false}]'::jsonb,
 null, 'Since some A are B, and all B are C, those particular A that are B must also be C, so it follows that some A are C.'),
('SSC-CGL', 'General Intelligence and Reasoning', 'Logical Reasoning (Syllogism, Statements and Conclusions)', 'medium', 'mcq',
 'Given: "No fish is a mammal" and "All whales are mammals." Which conclusion follows?',
 '[{"text":"No whale is a fish.","isCorrect":true},{"text":"All whales are fish.","isCorrect":false},{"text":"Some fish are whales.","isCorrect":false},{"text":"No conclusion can be drawn.","isCorrect":false}]'::jsonb,
 null, 'Since all whales are mammals, and no fish is a mammal, it follows that no whale can be a fish.'),

-- General Intelligence and Reasoning: Analytical Reasoning (Coding-Decoding, Blood Relations, Direction Sense)
('SSC-CGL', 'General Intelligence and Reasoning', 'Analytical Reasoning (Coding-Decoding, Blood Relations, Direction Sense)', 'medium', 'mcq',
 'In a certain code, "BOOK" is written as "DQQM". How is "PAGE" written in the same code?',
 '[{"text":"RCIG","isCorrect":true},{"text":"RCHF","isCorrect":false},{"text":"QCIG","isCorrect":false},{"text":"RCIH","isCorrect":false}]'::jsonb,
 null, 'Each letter is shifted forward by 2 positions in the alphabet (B to D, O to Q, O to Q, K to M); applying the same shift to P-A-G-E gives R-C-I-G.'),
('SSC-CGL', 'General Intelligence and Reasoning', 'Analytical Reasoning (Coding-Decoding, Blood Relations, Direction Sense)', 'hard', 'mcq',
 'Pointing to a photograph, a man says, "She is the daughter of my grandfather''s only son." How is the woman related to the man?',
 '[{"text":"Mother","isCorrect":false},{"text":"Sister","isCorrect":true},{"text":"Aunt","isCorrect":false},{"text":"Wife","isCorrect":false}]'::jsonb,
 null, 'The man''s grandfather''s only son must be the man''s own father (since he has no brothers), so the daughter of the man''s father is his sister.'),
('SSC-CGL', 'General Intelligence and Reasoning', 'Analytical Reasoning (Coding-Decoding, Blood Relations, Direction Sense)', 'medium', 'mcq',
 'Ravi walks 5 km towards north, then turns right and walks 3 km, then turns right again and walks 5 km. How far is he from his starting point?',
 '[{"text":"3 km","isCorrect":true},{"text":"5 km","isCorrect":false},{"text":"8 km","isCorrect":false},{"text":"13 km","isCorrect":false}]'::jsonb,
 null, 'After walking north 5 km, east 3 km, and south 5 km, the northward and southward legs cancel out, leaving Ravi 3 km east of his starting point.'),
('SSC-CGL', 'General Intelligence and Reasoning', 'Analytical Reasoning (Coding-Decoding, Blood Relations, Direction Sense)', 'medium', 'mcq',
 'A man walks 4 km towards east, then turns left and walks 4 km, then turns left again and walks 4 km. In which direction is he now from his starting point?',
 '[{"text":"North","isCorrect":true},{"text":"South","isCorrect":false},{"text":"East","isCorrect":false},{"text":"West","isCorrect":false}]'::jsonb,
 null, 'Tracking the path: east 4km, then north 4km (left turn from east), then west 4km (left turn from north) -- the net displacement from the start is 4km due north.'),

