-- Quantitative Aptitude: Arithmetic (Percentage, Profit-Loss, SI-CI, Ratio)
('SSC-CGL', 'Quantitative Aptitude', 'Arithmetic (Percentage, Profit-Loss, SI-CI, Ratio)', 'easy', 'mcq',
 'If the marked price of an item is Rs. 1000 and a discount of 10% is given, the selling price is:',
 '[{"text":"Rs. 900","isCorrect":true},{"text":"Rs. 950","isCorrect":false},{"text":"Rs. 800","isCorrect":false},{"text":"Rs. 990","isCorrect":false}]'::jsonb,
 null, 'A 10% discount on Rs. 1000 is Rs. 100, so the selling price is 1000-100=900.'),
('SSC-CGL', 'Quantitative Aptitude', 'Arithmetic (Percentage, Profit-Loss, SI-CI, Ratio)', 'medium', 'mcq',
 'A sum of Rs. 5000 is invested at 10% per annum compound interest for 2 years. Find the compound interest earned.',
 '[{"text":"Rs. 1000","isCorrect":false},{"text":"Rs. 1050","isCorrect":true},{"text":"Rs. 1100","isCorrect":false},{"text":"Rs. 500","isCorrect":false}]'::jsonb,
 null, 'Amount = 5000*(1.1)^2 = 5000*1.21 = 6050; Compound Interest = 6050-5000 = 1050.'),
('SSC-CGL', 'Quantitative Aptitude', 'Arithmetic (Percentage, Profit-Loss, SI-CI, Ratio)', 'medium', 'mcq',
 'Two numbers are in the ratio 5:7. If their sum is 144, find the smaller number.',
 '[{"text":"55","isCorrect":false},{"text":"60","isCorrect":true},{"text":"65","isCorrect":false},{"text":"70","isCorrect":false}]'::jsonb,
 null, 'Let the numbers be 5x and 7x; 5x+7x=144 gives x=12, so the smaller number is 5*12=60.'),
('SSC-CGL', 'Quantitative Aptitude', 'Arithmetic (Percentage, Profit-Loss, SI-CI, Ratio)', 'hard', 'mcq',
 'If the cost price of 10 articles equals the selling price of 8 articles, find the profit percentage.',
 '[{"text":"20%","isCorrect":false},{"text":"25%","isCorrect":true},{"text":"12.5%","isCorrect":false},{"text":"30%","isCorrect":false}]'::jsonb,
 null, '10*CP = 8*SP, so SP/CP = 10/8 = 1.25, meaning a 25% profit.'),

-- Quantitative Aptitude: Algebra
('SSC-CGL', 'Quantitative Aptitude', 'Algebra', 'medium', 'mcq',
 'Find the roots of the equation x^2 - 5x + 6 = 0.',
 '[{"text":"2 and 3","isCorrect":true},{"text":"1 and 6","isCorrect":false},{"text":"-2 and -3","isCorrect":false},{"text":"2 and -3","isCorrect":false}]'::jsonb,
 null, 'Factoring x^2-5x+6=(x-2)(x-3)=0 gives roots x=2 and x=3.'),
('SSC-CGL', 'Quantitative Aptitude', 'Algebra', 'easy', 'mcq',
 'Simplify: (a+b)^2 - (a-b)^2.',
 '[{"text":"2ab","isCorrect":false},{"text":"4ab","isCorrect":true},{"text":"a^2+b^2","isCorrect":false},{"text":"0","isCorrect":false}]'::jsonb,
 null, 'Expanding both squares: (a^2+2ab+b^2) - (a^2-2ab+b^2) = 4ab.'),
('SSC-CGL', 'Quantitative Aptitude', 'Algebra', 'easy', 'mcq',
 'If 2x + 3y = 12 and x = 3, find the value of y.',
 '[{"text":"1","isCorrect":false},{"text":"2","isCorrect":true},{"text":"3","isCorrect":false},{"text":"4","isCorrect":false}]'::jsonb,
 null, 'Substituting x=3: 2*3+3y=12, so 6+3y=12, giving 3y=6 and y=2.'),
('SSC-CGL', 'Quantitative Aptitude', 'Algebra', 'easy', 'mcq',
 'Find the value of x if 3x - 7 = 11.',
 '[{"text":"5","isCorrect":false},{"text":"6","isCorrect":true},{"text":"7","isCorrect":false},{"text":"8","isCorrect":false}]'::jsonb,
 null, '3x-7=11 gives 3x=18, so x=6.'),

